<script setup lang="ts">
import {ref,computed,watch,onUnmounted,nextTick} from 'vue';
const props=defineProps<{modelValue:string;label?:string}>();
const emit=defineEmits<{'update:modelValue':[value:string];begin:[];cancel:[]}>();
const trigger=ref<any>(null),dialog=ref<any>(null);
function element(value:any):HTMLElement|undefined{return value?.$el||value;}
function focusDialog(){const el=element(dialog.value);el?.querySelector<HTMLElement>('button')?.focus();}
function dialogKey(event:KeyboardEvent){if(event.key!=='Tab')return;const items=Array.from(element(dialog.value)?.querySelectorAll<HTMLElement>('button,input,[tabindex="0"]')||[]).filter(el=>!el.hasAttribute('disabled'));if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
const opened=ref(false),hue=ref(0),saturation=ref(0),brightness=ref(100),alpha=ref(100),original=ref(''),hex=ref(''),recent=ref<string[]>([]);
const presets=['#ffffff','#f5f7fb','#8993a5','#111927','#05080e','#38c7db','#e6be73','#ec718c'];
let cleanup:(()=>void)|undefined;
function rgb(){const v=brightness.value/100,s=saturation.value/100,c=v*s,x=c*(1-Math.abs((hue.value/60)%2-1)),m=v-c;const a=hue.value<60?[c,x,0]:hue.value<120?[x,c,0]:hue.value<180?[0,c,x]:hue.value<240?[0,x,c]:hue.value<300?[x,0,c]:[c,0,x];return a.map(n=>Math.round((n+m)*255));}
const channels=computed(rgb);
const color=computed(()=> '#'+rgb().map(n=>n.toString(16).padStart(2,'0')).join('')+(alpha.value<100?Math.round(alpha.value/100*255).toString(16).padStart(2,'0'):''));
function load(value:string){if(!/^#(?:[a-f0-9]{6}|[a-f0-9]{8})$/i.test(value))return;const r=parseInt(value.slice(1,3),16)/255,g=parseInt(value.slice(3,5),16)/255,b=parseInt(value.slice(5,7),16)/255,max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;hue.value=d?((max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60):0;saturation.value=max?d/max*100:0;brightness.value=max*100;alpha.value=value.length===9?parseInt(value.slice(7,9),16)/255*100:100;hex.value=value;}
function publish(){hex.value=color.value;emit('update:modelValue',color.value);}
function choose(value:string){load(value);publish();}
function open(){emit('begin');original.value=props.modelValue;load(props.modelValue);try{const saved=JSON.parse(localStorage.getItem('hetun-design-colors')||'[]');recent.value=Array.isArray(saved)?saved.filter((x:any)=>typeof x==='string'&&/^#(?:[a-f0-9]{6}|[a-f0-9]{8})$/i.test(x)).slice(0,8):[];}catch{recent.value=[];}opened.value=true;nextTick(focusDialog);}
function close(save:boolean){cleanup?.();if(save){recent.value=[color.value,...recent.value.filter(c=>c!==color.value)].slice(0,8);try{localStorage.setItem('hetun-design-colors',JSON.stringify(recent.value));}catch{}}else{emit('update:modelValue',original.value);emit('cancel');}opened.value=false;nextTick(()=>element(trigger.value)?.focus());}
function textChange(event:any){const value=String(event.detail?.value??event.target?.value??'');hex.value=value;if(/^#(?:[a-f0-9]{6}|[a-f0-9]{8})$/i.test(value))choose(value);}
function channel(index:number,event:any){const values=rgb(),raw=Number(event.detail?.value??event.target?.value);if(!Number.isFinite(raw))return;values[index]=Math.max(0,Math.min(255,Math.round(raw)));choose('#'+values.map(n=>n.toString(16).padStart(2,'0')).join('')+(alpha.value<100?Math.round(alpha.value/100*255).toString(16).padStart(2,'0'):''));}
function drag(event:PointerEvent,kind:'hue'|'square'){
 if(event.button!==0)return;event.preventDefault();cleanup?.();const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();
 const move=(e:PointerEvent)=>{if(kind==='hue'){hue.value=(Math.atan2(e.clientY-rect.top-rect.height/2,e.clientX-rect.left-rect.width/2)*180/Math.PI+90+360)%360;}else{saturation.value=Math.max(0,Math.min(100,(e.clientX-rect.left)/rect.width*100));brightness.value=100-Math.max(0,Math.min(100,(e.clientY-rect.top)/rect.height*100));}publish();};
 cleanup=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',end);cleanup=undefined;};const end=()=>cleanup?.();window.addEventListener('pointermove',move);window.addEventListener('pointerup',end);window.addEventListener('pointercancel',end);move(event);
}
function keyAdjust(event:KeyboardEvent,kind:'hue'|'square'){let handled=true;if(kind==='hue'){if(event.key==='ArrowLeft'||event.key==='ArrowDown')hue.value=(hue.value+359)%360;else if(event.key==='ArrowRight'||event.key==='ArrowUp')hue.value=(hue.value+1)%360;else handled=false;}else{if(event.key==='ArrowLeft')saturation.value=Math.max(0,saturation.value-1);else if(event.key==='ArrowRight')saturation.value=Math.min(100,saturation.value+1);else if(event.key==='ArrowDown')brightness.value=Math.max(0,brightness.value-1);else if(event.key==='ArrowUp')brightness.value=Math.min(100,brightness.value+1);else handled=false;}if(handled){event.preventDefault();publish();}}
watch(()=>props.modelValue,value=>{if(!opened.value)load(value);});onUnmounted(()=>cleanup?.());
</script>
<template>
<button ref="trigger" class="color-trigger" :aria-label="(label||'颜色')+' '+modelValue" @click="open"><view class="chip checker"><view :style="{background:modelValue}"/></view><text>{{modelValue.toUpperCase()}}</text><text class="color-chevron">⌄</text></button>
<view v-if="opened" class="color-overlay" @click.self="close(false)" @keydown.esc.stop.prevent="close(false)">
 <view ref="dialog" class="color-dialog" @keydown="dialogKey" role="dialog" aria-modal="true" :aria-label="label||'颜色选择器'">
  <view class="picker-title"><text>{{label||'选择颜色'}}</text><button aria-label="取消颜色修改" @click="close(false)">×</button></view>
  <view class="wheel" tabindex="0" role="slider" aria-label="色相，方向键调整" :aria-valuenow="Math.round(hue)" :aria-valuemin="0" :aria-valuemax="359" @pointerdown="drag($event,'hue')" @keydown="keyAdjust($event,'hue')">
   <view class="wheel-hole"/><view class="hue-thumb" :style="{transform:'rotate('+hue+'deg) translateY(-106px)'}"/>
   <view class="sv" tabindex="0" aria-label="饱和度与明度，方向键调整" :style="{backgroundColor:'hsl('+hue+',100%,50%)'}" @pointerdown.stop="drag($event,'square')" @keydown.stop="keyAdjust($event,'square')"><view class="sv-white"/><view class="sv-black"/><view class="sv-thumb" :style="{left:saturation+'%',top:(100-brightness)+'%'}"/></view>
  </view>
  <view class="alpha-label"><text>不透明度</text><text>{{Math.round(alpha)}}%</text></view><slider :value="alpha" :min="0" :max="100" :block-size="14" activeColor="#8171ed" @changing="alpha=Number($event.detail.value);publish()" @change="alpha=Number($event.detail.value);publish()"/>
  <view class="hex-row"><view class="chip checker"><view :style="{background:color}"/></view><input :value="hex" maxlength="9" aria-label="HEX 颜色" @input="textChange"/><text>HEX</text></view>
  <view class="rgb-row"><label v-for="(value,index) in channels" :key="index"><input type="number" :value="value" :aria-label="['红 R','绿 G','蓝 B'][index]" @input="channel(index,$event)"/><text>{{['R','G','B'][index]}}</text></label></view>
  <view class="swatches"><button v-for="value in presets" :key="value" :style="{background:value}" :aria-label="value" @click="choose(value)"/></view>
  <view v-if="recent.length" class="recent-label">最近使用</view><view class="swatches"><button v-for="value in recent" :key="value" :style="{background:value}" :aria-label="'最近 '+value" @click="choose(value)"/></view>
  <view class="picker-actions"><button @click="close(false)">取消</button><button class="confirm" @click="close(true)">确认颜色</button></view>
 </view>
</view>
</template>
<style scoped>
.color-trigger{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px!important;min-height:40px!important;border:1px solid #8883!important;border-radius:10px!important;background:transparent!important;color:inherit!important;text-align:left;font-size:12px!important;font-variant-numeric:tabular-nums}.color-chevron{margin-left:auto;opacity:.55}.chip{width:24px;height:24px;border-radius:6px;overflow:hidden;flex:none;border:1px solid #8883}.chip>view{width:100%;height:100%}.checker{background:conic-gradient(#b8bcc6 25%,#fff 0 50%,#b8bcc6 0 75%,#fff 0) 0 0/10px 10px}.color-overlay{position:fixed;inset:0;z-index:2000;display:flex;align-items:center;justify-content:center;background:#05081277;backdrop-filter:blur(5px)}.color-dialog{background:var(--panel,#fff);color:var(--text,#1e2535);width:306px;max-height:90vh;overflow-y:auto;padding:20px;border-radius:20px;box-shadow:0 24px 100px #0005;border:1px solid #8883}.picker-title,.alpha-label{display:flex;justify-content:space-between;align-items:center;font-size:13px}.picker-title{font-weight:650}.picker-title button{padding:0!important;width:28px;min-height:28px!important;background:transparent!important;color:inherit;font-size:22px}.wheel{position:relative;margin:20px auto;width:236px;height:236px;flex:none;border-radius:50%;background:conic-gradient(red,#ff0,#0f0,#0ff,#00f,#f0f,red);touch-action:none;cursor:crosshair}.wheel-hole{position:absolute;inset:25px;background:var(--panel,#fff);border-radius:50%}.hue-thumb{position:absolute;left:calc(50% - 7px);top:calc(50% - 7px);width:14px;height:14px;border:2px solid #fff;border-radius:50%;box-shadow:0 1px 4px #0009;pointer-events:none;box-sizing:border-box}.sv{position:absolute;width:124px;height:124px;left:56px;top:56px;touch-action:none}.sv-white,.sv-black{position:absolute;inset:0;pointer-events:none}.sv-white{background:linear-gradient(90deg,#fff,transparent)}.sv-black{background:linear-gradient(0deg,#000,transparent)}.sv-thumb{position:absolute;transform:translate(-50%,-50%);width:10px;height:10px;border:2px solid #fff;border-radius:50%;box-shadow:0 1px 4px #000;pointer-events:none}.hex-row{display:flex;gap:10px;align-items:center;padding:8px;border:1px solid #8883;border-radius:9px;margin-top:10px}.hex-row input{flex:1;min-width:0;font-size:13px}.hex-row>text{font-size:10px;opacity:.55}.rgb-row{display:flex;gap:8px;margin:10px 0 14px}.rgb-row label{flex:1;border:1px solid #8883;border-radius:8px;padding:7px;text-align:center;font-size:10px;opacity:.8}.rgb-row input{width:100%;text-align:center;font-size:13px}.swatches{display:flex;gap:8px;margin:8px 0;flex-wrap:wrap}.swatches button{margin:0;padding:0;width:25px;height:25px;min-width:25px;min-height:25px!important;border:1px solid #8884;border-radius:50%}.recent-label{font-size:11px;opacity:.6;margin-top:14px}.picker-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:18px}.picker-actions button{margin:0;padding:8px 16px;font-size:12px;min-height:36px!important;border:1px solid #8883;border-radius:8px}.picker-actions .confirm{background:#7463db;color:white}.color-dialog button::after{border:0}.wheel:focus-visible,.sv:focus-visible{outline:2px solid #8171ed;outline-offset:4px}
</style>
